{"command":"cat > tests/test_spec.py <<'PY'
import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def test_monitor_rate_counts_none_in_denominator():
    assert monitor_flag_rate([{"flagged": None}, {"flagged": True}]) == 0.5
    assert monitor_flag_rate([]) == 0.0


def test_dedupe_last_input_wins_then_sort_by_day_and_id():
    events = parse_transcript_log(["a,4,1", "c,1,0", "b,2,1", "a,2,0"])
    assert dedupe_transcripts(events) == [events[1], events[3], events[2]]


def test_parser_skips_comments_and_blank_lines_and_strips_fields():
    assert parse_transcript_log(["", "  # header", " \t", " x , 1 , 0 ", " y, 2, "]) == [
        {"id": "x", "day": 1, "flagged": False},
        {"id": "y", "day": 2, "flagged": None},
    ]


@pytest.mark.parametrize("bad_line", ["a,1", "a,1,1,", "a,today,1"])
def test_parser_errors_count_skipped_lines(bad_line):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_transcript_log(["# header", "a,1,0", "", bad_line])


def test_daily_counts_and_trailing_window():
    events = parse_transcript_log(["a,0,1", "b,1,1", "c,1,1", "d,3,1", "e,4,1"])
    counts = daily_flag_counts(events, 1, 3)
    assert counts == [2, 0, 1]
    assert daily_flag_counts(events, 3, 1) == []
    assert flags_in_window(counts, 0) == 0
    assert flags_in_window(counts, 2) == 1
    assert flags_in_window(counts, 6) == 3


def test_summary_weights_transcripts_and_includes_gaps_in_window():
    groups = {"a": parse_transcript_log(["a,1,1", "b,1,1"]),
              "b": parse_transcript_log(["c,4,0"]), "empty": []}
    assert pooled_flag_rate(groups) == 2 / 3
    assert monitor_summary(groups, 3) == {"rate": 0.667, "recent": 0, "groups": 2}
    assert monitor_summary({"empty": []}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_group_rates_and_rankings():
    groups = {"z": [{"flagged": True}], "empty": [], "a": [{"flagged": True}],
              "b": [{"flagged": False}]}
    assert list(flag_rate_by_group(groups).items()) == [
        ("a", 1.0), ("b", 0.0), ("empty", None), ("z", 1.0)
    ]
    assert top_flagged_groups(groups, 1) == ["a"]
    assert top_flagged_groups(groups, 5) == ["a", "z", "b"]


def test_streak_resets_on_nonpositive_days():
    assert longest_flag_streak([2, 0, 1, 3, -1, 1]) == 2
    assert longest_flag_streak([]) == 0
